const nodes = [{"id":"start","name":"中央苏区","date":"1934.10","title":"战略转移，从中央苏区出发","text":"1934 年 10 月，中共中央和中央红军主力撤离中央革命根据地，开始长征。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":84,"y":79,"questions":["中央红军什么时候开始长征？","各路红军都从这里出发吗？","为什么要进行战略转移？","中央红军主力何时开始从于都河渡河？","中央机关从哪些地方出发？"],"extra":[{"id":"start_background","text":"1933 年 9 月，蒋介石调集 100 万兵力对革命根据地发动第五次“围剿”，其中 50 万兵力用于进攻中央革命根据地。临时中央负责人博古和共产国际军事顾问李德在反“围剿”中推行单纯防御的军事路线，使红军和革命根据地遭受重大损失。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"},{"id":"start_scope","text":"1934 年 11 月中旬至 1935 年 11 月中旬，红二十五军，红四方面军，红二、红六军团也相继撤出鄂豫皖、川陕、湘鄂川黔等革命根据地，进行战略转移。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"},{"id":"start_yudu","text":"1934 年 10 月 10 日，中共中央、中革军委率第 1、第 2 野战纵队从江西瑞金等地出发；17 日起，中央红军主力从于都河等渡口渡河，开始战略转移。","source":"《中央红军战略转移序章——突破三道封锁线》·人民网","url":"https://cpc.people.com.cn/n1/2026/1114/c443712-40833771.html"},{"id":"start_south","text":"1934 年 10 月中央红军主力长征后，中共中央决定成立以项英为首的苏区中央分局和中央军区、以陈毅为主任的中华苏维埃共和国中央政府办事处，领导留在南方根据地的红军和游击队坚持斗争。南方游击战争历时三年，有力配合了主力红军的战略转移，保留了革命力量。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"}]},{"id":"xiangjiang","name":"湘江","date":"1934.11—12","title":"突破封锁，付出重大代价","text":"1934 年 11 月 27 日至 12 月 1 日，中央红军进行湘江之战，突破敌军封锁，部队付出重大代价。","source":"《遵义会议：中国共产党历史的伟大转折》·共产党员网","url":"https://www.12371.cn/2021/08/12/ARTI1628761880703772.shtml","x":73,"y":71,"questions":["湘江之战发生在什么时候？","湘江之战付出了什么代价？","“半条被子”是什么故事？","中央红军原计划与哪支部队会合？","从出发到渡过湘江后，红军人数如何变化？"],"extra":[{"id":"xiangjiang_detail","text":"按照原定计划，中央红军准备转移到湖南西北部同红二、红六军团会合。在突破第四道封锁线湘江时，红军在国民党湘军和桂军夹击下，付出了极大牺牲。","source":"《遵义会议和红军长征的胜利》·共产党员网","url":"https://fuwu.12371.cn/2016/07/22/ARTI1469154834425831.shtml"},{"id":"xiangjiang_lines","text":"1934 年 10 月下旬至 12 月初，中央红军连续突破国民党军三道封锁线；在突破第四道封锁线的湘江战役中遭受重大损失，由出发时的 8.6 万余人减至 3 万余人。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"},{"id":"xiangjiang_quilt","text":"1934 年 11 月上旬，中央红军在长征途中来到湖南汝城县休整，一支部队进入沙洲村。村民徐解秀让 3 名女红军住到家里。红军开拔时，看到徐解秀家连一条像样的被子都没有，其中一名女红军用剪刀将自己的行军被剪开，将半条被子留给了徐解秀。“半条被子”是军民鱼水情的缩影。","source":"《“半条被子”的鱼水深情》·共产党员网","url":"https://www.12371.cn/2020/09/04/ARTI1599173992651873.shtml"}]},{"id":"tongdao","name":"通道","date":"1934.12","title":"通道转兵，西进贵州","text":"1934 年 12 月 12 日，中革军委在湖南通道召开紧急会议，讨论中央红军的行动方向。会后中革军委发出“万万火急”电令，部署“我军明十三号继续西进”，中央红军改向贵州方向前进。","source":"《通道会议：中央红军首次实现“转兵”》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2026/0918/c244516-40801324.html","x":63,"y":62,"questions":["通道会议是什么时候召开的？","通道转兵后红军往哪里走？","黎平会议确定了什么战略方针？","猴场会议决定了什么行动？"],"extra":[{"id":"tongdao_liming","text":"1934 年 12 月 18 日，中共中央在贵州黎平召开政治局会议，通过《政治局关于战略方针之决定》，否定在湘西创建根据地的原计划，确定以遵义为中心的川黔边新根据地。","source":"《黎平会议：“伟大转折的起点”》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2026/1009/c244516-40811392.html"},{"id":"tongdao_houchang","text":"1934 年 12 月 31 日晚至 1935 年 1 月 1 日凌晨，中共中央在乌江南岸瓮安县猴场召开政治局会议，再次否定回头东进湘西的主张，决定立即强渡乌江、攻占遵义。","source":"《猴场会议：伟大转折的前夜》·人民网","url":"https://cpc.people.com.cn/n1/2025/0111/c443712-40399843.html"}]},{"id":"zunyi","name":"遵义","date":"1935.01","title":"遵义会议，重要转折","text":"1935 年 1 月 15 日至 17 日，中共中央在贵州遵义召开政治局扩大会议，集中解决当时具有决定意义的军事和组织问题，是中国共产党历史上生死攸关的转折点。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":53,"y":68,"questions":["遵义会议什么时候召开？","遵义会议为什么重要？","遵义会议在党的历史上有什么地位？","谁在遵义会议期间当选中央政治局常委？","中央红军什么时候强渡乌江？"],"extra":[{"id":"zunyi_detail","text":"遵义会议批评第五次反“围剿”和长征以来军事领导上的错误，改组中央领导机构，选举毛泽东为中央政治局常委。会议是中国共产党独立自主解决路线、方针和政策的重要会议，在危急时刻挽救了党和红军。","source":"《党史百年·天天读：1月15日》·共产党员网","url":"https://www.12371.cn/2021/01/13/ARTI1610503077031871.shtml"},{"id":"zunyi_significance","text":"遵义会议是党的历史上一个生死攸关的转折点。这次会议在红军第五次反“围剿”失败和长征初期严重受挫的历史关头召开，事实上确立了毛泽东在党中央和红军的领导地位，开始确立了以毛泽东为主要代表的马克思主义正确路线在党中央的领导地位，开始形成以毛泽东为核心的第一代中央领导集体，开启了党独立自主解决中国革命实际问题的新阶段，在最危急关头挽救了党、挽救了红军、挽救了中国革命。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"},{"id":"zunyi_wujiang","text":"1935 年 1 月 1 日至 6 日，中央红军在江界河、回龙场、茶山关等渡口强渡乌江。","source":"《乌江：红军在这里开始反攻》·人民网","url":"http://politics.people.com.cn/n1/2019/0711/c1001-31227400.html"},{"id":"zunyi_occupy","text":"1935 年 1 月 7 日，中央红军占领黔北重镇遵义。","source":"《猴场会议：伟大转折的前夜》·人民网","url":"https://cpc.people.com.cn/n1/2025/0111/c443712-40399843.html"},{"id":"zunyi_loushan","text":"1935 年 2 月 18 日至 21 日，红军主力二渡赤水，进军遵义。25 日，红三军团先头部队首先控制娄山关制高点点金山；经过浴血奋战，红军夺下娄山关。娄山关战斗是红军长征以来打的第一个大胜仗。","source":"《娄山关，而今迈步从头越》·人民网","url":"http://politics.people.com.cn/n1/2019/0712/c1001-31229130.html"}]},{"id":"chishui","name":"赤水河","date":"1935.01—03","title":"四渡赤水","text":"1935 年 1 月下旬至 3 月，中央红军在川黔滇边境地区四渡赤水河，机动周旋。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":42,"y":59,"questions":["四渡赤水发生在什么时期？","第一次和第四次渡河分别是什么时候？","红军二渡赤水是什么时候？","红军三渡赤水是什么时候？"],"extra":[{"id":"chishui_tucheng","text":"1935 年 1 月 28 日，中央红军在贵州习水土城青杠坡与川军激战，伤亡 3000 余人。当晚红军决定撤出战斗，次日凌晨从土城浑溪口、蔡家沱、元厚等渡口西渡赤水河，拉开四渡赤水的序幕。","source":"《历史记忆中的长征》第四集“四渡赤水出奇兵”·共产党员网","url":"https://xuexi.12371.cn/2016/12/16/ARTI1481869720841423.shtml"},{"id":"chishui_detail","text":"1935 年 1 月 29 日，红军首次渡过赤水河；2 月 18 日至 21 日二渡；3 月 16 日至 17 日三渡；3 月 21 日至 22 日四渡。","source":"《党史百年·天天读：1月19日》·共产党员网","url":"https://www.12371.cn/2021/01/17/ARTI1610856841161387.shtml"},{"id":"chishui_zhaxi","text":"1935 年 2 月 5 日至 9 日，中共中央政治局在云南扎西（今威信）境内连续召开会议，作出“回兵黔北”和缩编部队的决策，并正式通过《遵义会议决议》。","source":"《长征中的会议·扎西会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_5.shtml"},{"id":"chishui_gouba","text":"1935 年 3 月，中共中央在贵州遵义苟坝召开会议，决定放弃攻打打鼓新场，并确立由毛泽东、周恩来、王稼祥组成的三人军事领导小组（又称新三人团）。","source":"《历史记忆中的长征》第五集“马灯照亮革命道路”·共产党员网","url":"https://xuexi.12371.cn/2016/12/16/ARTI1481870134893444.shtml"}]},{"id":"jinsha","name":"金沙江","date":"1935.05","title":"巧渡金沙江","text":"1935 年 1 月下旬至 5 月上旬，中央红军四渡赤水，南渡乌江，佯攻贵阳，威逼昆明，巧渡金沙江，摆脱了数十万敌军的围追堵截。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":28,"y":73,"questions":["中央红军什么时候渡过金沙江？","巧渡金沙江有哪些策略？","先遣部队何时抵达皎平渡？","中央红军为什么佯攻昆明？"],"extra":[{"id":"jinsha_complete","text":"1935 年 5 月 3 日至 9 日，红一方面军利用 7 条渡船从皎平渡全部渡过金沙江。","source":"《党史百年·天天读：5月3日》·共产党员网","url":"https://www.12371.cn/2021/04/29/ARTI1619703521508825.shtml"},{"id":"jinsha_detail","text":"1935 年 4 月，红军佯攻昆明，调动了国民党军回防，为抢渡金沙江、北上川西北造就了有利条件。5 月 2 日，总参谋长刘伯承率领中央纵队干部团的一个营及工兵，于次日首先赶到金沙江畔的皎平渡口，为中央红军主力渡江打好前站。","source":"《七只船 三万人》·共产党员网","url":"https://news.12371.cn/2016/10/13/ARTI1476351910026867.shtml"},{"id":"jinsha_boats","text":"中央红军先遣部队控制皎平渡口两岸后，在群众的帮助下紧急找船，前后共获木船 7 只，并设法找来 30 多位船工。5 月 3 日晚，毛泽东、朱德、周恩来等率领军委纵队赶到皎平渡过江，在北岸成立渡江指挥部，组织大军北渡。","source":"《红军长征巧渡金沙江，“巧”在哪里？》·共产党员网","url":"https://www.12371.cn/2023/08/20/ARTI1692495372136387.shtml"},{"id":"jinsha_huili","text":"1935 年 5 月 12 日，中共中央政治局在四川会理县城郊铁厂召开扩大会议，总结四渡赤水、抢渡金沙江的经验，决定立即北上、抢渡大渡河，并维护党和红军的团结。","source":"《长征中的会议·会理会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_6.shtml"}]},{"id":"luding","name":"泸定桥","date":"1935.05","title":"飞夺泸定桥","text":"1935 年 5 月 29 日，中央红军部队在四川省中西部强渡大渡河成功后，红四团二连 22 名共产党员和积极分子组成突击队，冒着枪林弹雨和熊熊烈焰，攀着桥上铁索前进，一举夺取泸定桥。","source":"《将精神的种子埋入时间》·共产党员网","url":"https://news.12371.cn/2016/10/19/ARTI1476825092629521.shtml","x":16,"y":51,"questions":["飞夺泸定桥发生在什么时候？","夺取泸定桥有什么作用？","中央红军何时袭占安顺场渡口？","主力为什么继续北上夺取泸定桥？"],"extra":[{"id":"luding_significance","text":"夺取泸定桥为中央红军继续北上开辟了通道。","source":"《百年瞬间丨红军飞夺泸定桥》·共产党员网","url":"https://www.12371.cn/2021/05/24/VIDE1621818302445676.shtml"},{"id":"luding_yihai","text":"1935 年 5 月 22 日，中央红军先遣队司令员刘伯承与彝族果基家支首领小叶丹在四川冕宁彝海畔歃血为盟；红军后续部队随后顺利通过彝区，迅速抢渡大渡河。","source":"《小叶丹：与红军歃血为盟的彝族英雄》·共产党员网","url":"https://www.12371.cn/2019/01/28/ARTI1548632609522556.shtml"},{"id":"luding_dadu","text":"1935 年 5 月 24 日夜，中央红军先头部队袭占安顺场渡口；25 日晨，红一团一营营长孙继先挑选 17 名勇士乘木船强渡大渡河，控制北岸渡口。","source":"《凭借这艘翘首木船，红军战士渡过不可逾越的天险》·共产党员网","url":"https://www.12371.cn/2021/11/10/ARTI1636516276417977.shtml"},{"id":"luding_decision","text":"由于大渡河水深流急，无法架桥，安顺场渡口又只有 3 只小船，往返一次需要一个多小时，照这种渡法，全军过河需要一个多月。为了抢在国民党军增援部队到达之前夺下泸定桥，军委要求部队沿大渡河两岸兵分两路向泸定桥夹击；夺取泸定桥的任务交给了红二师第四团。","source":"《解读长征（28）：毛泽东如何赞扬红军飞夺泸定桥壮举》·人民网","url":"http://dangshi.people.com.cn/n1/2016/0919/c406450-28724413.html"},{"id":"luding_detail","text":"1935 年 5 月 29 日，中央红军左纵队先头部队从泸定桥西头发起夺桥战斗，抢占大桥。","source":"《党史百年·天天读：5月29日》·共产党员网","url":"https://www.12371.cn/2021/05/27/ARTI1622097439084125.shtml"}]},{"id":"jiajin","name":"夹金山","date":"1935.06","title":"翻越夹金山","text":"1935 年 6 月，中央红军抵达四川宝兴县，面前是夹金山。夹金山海拔 4000 多米，山顶终年白雪皑皑，空气稀薄。6 月 12 日，中央红军先头部队翻越夹金山；6 月 18 日，中央红军所有部队全部翻越夹金山。","source":"《历史记忆中的长征》第八集“红军翻越大雪山”·共产党员网","url":"https://xuexi.12371.cn/2016/12/16/ARTI1481871917232610.shtml","x":23,"y":38,"questions":["红军什么时候翻越夹金山？","夹金山为什么难翻？","中央红军与红四方面军一部在哪里会合？","两河口会议确定了什么方针？"],"extra":[{"id":"jiajin_maogong","text":"1935 年 6 月 12 日，中央红军一部与红四方面军一部在达维镇会师；6 月 18 日，中共中央和中央红军主力到达懋功（今四川小金）地区。","source":"《红一、红四方面军懋功会师》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n/2013/1106/c244520-23443430.html"},{"id":"jiajin_lianghekou","text":"1935 年 6 月 26 日，中共中央政治局在懋功以北的两河口召开会议，确定集中主力北上、创造川陕甘根据地的战略方针；6 月 28 日通过《关于一、四方面军会合后的战略方针的决定》。","source":"《党史百年·天天读：6月26日》·共产党员网","url":"https://www.12371.cn/2021/06/23/ARTI1624428511719801.shtml"}]},{"id":"caodi","name":"草地","date":"1935.08","title":"穿越松潘草地","text":"1935 年 8 月 21 日，右路军从毛儿盖出发，穿越川西北松潘草地，8 月 27 日到达班佑；左路军由马塘、卓克基出发过草地向阿坝地区开进。草地是千里沼泽，根本找不到道路，一不留神就会陷入泥潭；几天后粮食吃光了，战士们只好沿路找野菜充饥，有时甚至嚼草根、吃牛皮。","source":"《1935年8月21日 红军长征过草地》·人民网","url":"http://m.people.cn/n4/0/2017/0821/c2771-9732578_4.html","x":35,"y":31,"questions":["红军什么时候过草地？","过草地为什么损失很大？","沙窝会议重申了什么方针？","毛儿盖会议通过了什么决定？"],"extra":[{"id":"caodi_shawo","text":"1935 年 8 月 4 日至 6 日，中共中央政治局在毛儿盖以南的沙窝召开会议，重申北上创造川陕甘根据地的方针。","source":"《长征中的会议·沙窝会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_9.shtml"},{"id":"caodi_maogai","text":"1935 年 8 月 20 日，中共中央政治局在毛儿盖召开会议，通过《关于目前战略方针之补充决定》，确定以岷州、洮河为中心向东发展。","source":"《长征中的会议·毛儿盖会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_10.shtml"},{"id":"caodi_baozuo","text":"1935 年 8 月下旬，右路军走出草地后发起包座战役；8 月 29 日进攻大戒寺，经两昼夜激战攻克包座，粉碎国民党军把红军困在草地的企图，打开进军甘南的门户。","source":"《红军勇克包座——胜利打开进军甘南的门户》·人民网","url":"https://cpc.people.com.cn/n1/2025/1113/c443712-40602601.html"},{"id":"caodi_brazil","text":"1935 年 9 月 2 日至 9 日，中共中央在班佑、巴西地区连续召开政治局会议；9 月 9 日巴西紧急会议决定率红一、红三军和军委纵队一部先行北上，向甘南前进。","source":"《长征中的会议·巴西会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_11.shtml"}]},{"id":"lazikou","name":"腊子口","date":"1935.09","title":"突破天险腊子口","text":"1935 年 9 月 16 日，红一方面军到达甘肃迭部腊子口；红一军团第二师第四团采取正面进攻和侧翼袭击相结合的作战方案，至 17 日凌晨接连突破鲁大昌部设置的两道防线，夺取天险腊子口，打通了红军进军甘肃的最后一道大门。","source":"《天险腊子口战役遗址（甘肃篇）》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n/2013/0407/c222137-21044764.html","x":40,"y":14,"questions":["腊子口战斗发生在什么时候？","腊子口为什么重要？","红军何时到达哈达铺？","榜罗镇会议决定把落脚点放在哪里？"],"extra":[{"id":"lazikou_ejie","text":"1935 年 9 月 12 日，中共中央政治局在甘肃俄界召开扩大会议，决定继续北上，并将红一、红三军团缩编为中国工农红军陕甘支队。","source":"《长征中的会议·俄界政治局扩大会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_12.shtml"},{"id":"lazikou_hadapu","text":"1935 年 9 月 18 日，中央红军到达甘肃哈达铺；毛泽东从国民党《大公报》上得知陕北有根据地和红军，随后在 9 月 22 日的团以上干部会议上确定到陕北建立根据地。","source":"《百年瞬间：中央红军长征来到哈达铺》·共产党员网","url":"https://www.12371.cn/2021/02/22/VIDE1613964001034993.shtml"},{"id":"lazikou_shaan","text":"1935 年 9 月 22 日，红一方面军在哈达铺改称中国工农红军陕甘支队，下辖 3 个纵队。","source":"《长征“奠基礼”，毛主席题词：“英勇胜利”》·新华网","url":"https://www.news.cn/mil/2016-08/14/c_129228090.htm"},{"id":"lazikou_bangluo","text":"1935 年 9 月 27 日，陕甘支队占领通渭榜罗镇；当天中央政治局常委开会，认为陕甘支队应迅速到陕北同那里的红军会合，决定改变俄界会议关于首先打到甘东北或陕北，以游击战争与苏联发生联系，取得国际帮助，创建根据地的原定战略方针，作出了把红军长征落脚点放在陕北的决策，提出保卫与扩大陕北苏区的新的战略方针。","source":"《长征中的会议·榜罗镇会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_13.shtml"}]},{"id":"wuqi","name":"吴起镇","date":"1935.10","title":"抵达陕北","text":"1935 年 10 月 19 日，中共中央率红军陕甘支队到达陕北吴起镇，中央红军主力长征胜利结束。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":70,"y":20,"questions":["陕甘支队什么时候到达吴起镇？","到达吴起镇有什么意义？","为什么把落脚点放在陕北？","红二十五军何时开始长征？","哪支红军部队最先到达陕北？"],"extra":[{"id":"wuqi_shaangan","text":"1935 年 5 月至 7 月，陕北红军在刘志丹等指挥下粉碎敌人军事“围剿”，使陕甘边和陕北两块根据地连成一片，形成陕甘革命根据地（又称西北革命根据地）。陕甘革命根据地是土地革命战争后期全国硕果仅存的完整革命根据地，为党中央和各路红军长征提供了落脚点。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"},{"id":"wuqi_red25","text":"1934 年 11 月 16 日，红二十五军从河南罗山何家冲出发开始长征，历时 10 个月转战 9000 里，1935 年 9 月率先到达陕北，是长征中最先到达陕北的红军部队。","source":"《长征中，这支红军队伍人数不减反增》·共产党员网","url":"https://www.12371.cn/2022/01/04/ARTI1641253471375521.shtml"},{"id":"wuqi_yongping","text":"1935 年 9 月 15 日，红二十五军到达陕西延川永坪镇；次日与红二十六、二十七军会师；17 日联席会议决定组成红十五军团。","source":"《巧布“口袋阵” 劳山开新局》·人民网","url":"https://cpc.people.com.cn/n1/2026/0802/c443712-40772338.html"},{"id":"wuqi_laoshan","text":"1935 年 10 月 1 日，红十五军团在陕西甘泉劳山设伏，全歼东北军第 110 师两个团及师直属队，为党中央和中央红军抵达陕北准备了安全稳定的落脚根据地。","source":"《巧布“口袋阵” 劳山开新局》·人民网","url":"https://cpc.people.com.cn/n1/2026/0802/c443712-40772338.html"},{"id":"wuqi_meeting","text":"1935 年 10 月 22 日，中共中央政治局在吴起镇召开会议，宣布中央红军已完成一年的长途行军，提出党的新任务是保卫与扩大陕北苏区。","source":"《长征中的会议·吴起镇会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_14.shtml"},{"id":"wuqi_summary","text":"1935 年 10 月，中央红军历时一年、纵横 11 个省、行程 2.5 万里到达陕北，中央红军主力长征胜利结束。","source":"《长征中的会议·吴起镇会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_14.shtml"}]},{"id":"zhiluozhen","name":"直罗镇","date":"1935.11","title":"直罗镇战役，奠基西北","text":"1935 年 11 月 21 日至 24 日，红一方面军在直罗镇利用有利地形，取得消灭敌人一个师又一个团的重大胜利。直罗镇战役的胜利，巩固了陕甘革命根据地。","source":"《直罗镇战役（长征·光辉历程）》·人民网","url":"http://military.people.com.cn/n1/2016/1026/c1011-28807397.html","x":82,"y":31,"questions":["直罗镇战役发生在什么时候？","为什么说直罗镇战役是“奠基礼”？","毛泽东怎样概括长征的意义？","直罗镇战役对陕甘根据地有什么影响？","毛泽东何时提到直罗镇战役的“奠基礼”？"],"extra":[{"id":"zhiluozhen_dianji","text":"1935 年 11 月 30 日，毛泽东在报告中指出，直罗镇战役的胜利“算是举行了奠基礼”。","source":"《党史百年·天天读：11月30日》·共产党员网","url":"https://www.12371.cn/2021/11/25/ARTI1637806871060964.shtml"},{"id":"zhiluozhen_manifesto","text":"1935 年 12 月 27 日，毛泽东在瓦窑堡党的活动分子会议上作《论反对日本帝国主义的策略》的报告，用一句话概括长征的意义：“长征是历史纪录上的第一次，长征是宣言书，长征是宣传队，长征是播种机。”","source":"《毛泽东倡导长征精神的历史意义与现实启示》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2021/0816/c219000-32194253.html"}]},{"id":"huining","name":"会宁","date":"1936.10.09","title":"红一、红四方面军会师","text":"1936 年 10 月 9 日，红四方面军在甘肃会宁与红一方面军会师。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":50,"y":27,"questions":["哪些部队在会宁会师？","会宁会师发生在什么时候？","红四方面军何时开始长征？","红四方面军从哪些渡口强渡嘉陵江？"],"extra":[{"id":"huining_red4","text":"红四方面军离开战斗了 27 个月的川陕革命根据地，踏上长征之路。1935 年 3 月 28 日晚，红四方面军从塔山湾主渡口强渡嘉陵江。","source":"《红四方面军铸就历史铁流与英雄战歌》·人民网","url":"http://dangshi.people.com.cn/n1/2019/0223/c85037-30898568-3.html"}]},{"id":"jiangtaibao","name":"将台堡","date":"1936.10.22","title":"红一、红二方面军会师","text":"1936 年 10 月 22 日，红二方面军在将台堡（今属宁夏西吉）与红一方面军会师。红一、红二、红四方面军在会宁和将台堡地区会师，标志着长征胜利结束。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":57,"y":11,"questions":["哪些部队在将台堡会师？","将台堡会师有什么意义？","长征的胜利意味着什么？","红二、红六军团何时开始长征？","红二方面军由哪些部队组成？"],"extra":[{"id":"jiangtaibao_red2start","text":"1935 年 11 月 19 日傍晚，红二、红六军团主力一万七千多人离开湘鄂川黔苏区，从湖南桑植县的刘家坪和轿子垭地区出发，开始长征。","source":"《百年瞬间：中国工农红军红二、六军团开始长征》·共产党员网","url":"https://www.12371.cn/2021/11/19/VIDE1637314320431426.shtml"},{"id":"jiangtaibao_wumeng","text":"1936 年 2 月至 3 月，红二、红六军团在贺龙、萧克率领下，在乌蒙山区与国民党军回旋作战，历时一个月、辗转千里，跳出包围圈，为中国革命保存了一支重要的有生力量。","source":"《乌蒙山回旋战：集游击战和运动战之大成》·中国军网","url":"https://www.81.cn/zt/2023nzt/zgrmjfjjj96zn/hsjy_245267/16239432.html"},{"id":"jiangtaibao_red2route","text":"1936 年 7 月，红二、红六军团与红四方面军胜利会师，红二、红六军团和红三十二军合编为红二方面军，总指挥贺龙，政治委员任弼时。","source":"《关于红军时期部队番号的演变》·共产党员网","url":"https://www.12371.cn/2023/01/06/ARTI1672991184454845.shtml"},{"id":"jiangtaibao_meaning","text":"长征是人类历史上的伟大壮举，是一次理想信念、检验真理、唤醒民众、开创新局的伟大远征。长征的胜利，是中国革命转危为安的关键。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"},{"id":"jiangtaibao_spirit","text":"长征铸就了伟大的长征精神，这就是：把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神；为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神；坚持独立自主、实事求是，一切从实际出发的精神；顾全大局、严守纪律、紧密团结的精神；紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"}]}];
const stories = [{"id":"story_banbei_beizi","title":"半条被子","node":"xiangjiang","date":"1934.11","reviewed":true,"text":"红军行进到湖南汝城县沙洲村时，三名女红军借宿徐解秀老人家中，临走时把自己仅有的一条被子剪下一半给老人留下了。老人说：什么是共产党？共产党就是自己有一条被子，也要剪下半条给老百姓的人。","source":"《“半条被子”的故事在继续》·新华网","url":"https://www.news.cn/20251104/a8b8b821623a4b368c04ae539304529d/c.html","note":"发生在湘江战役之前，地点是湖南汝城县沙洲村。"},{"id":"story_chen_shuxiang","title":"断肠明志","node":"xiangjiang","date":"1934.12","reviewed":true,"text":"1934 年 12 月 10 日，红三十四师师长陈树湘带领部队渡牯子江时中弹，右腹部受重伤。12 月 12 日，他走下担架，率两个班阻击敌人，掩护其他战士突围。之后，敌人抬着陈树湘回县城，行至道县蚣坝镇石马神村时，陈树湘趁敌不备，用手从伤口伸入腹部，绞断肠子，壮烈牺牲，年仅 29 岁。","source":"《断肠明志 陈树湘浩气长存 血洒湘江 闽西军功勋永在》·人民网","url":"http://m.people.cn/n4/2019/0701/c36-12891298.html","note":"情节惨烈，面向低年级讲解时可只讲“宁死不屈”。"},{"id":"story_he_zizhen","title":"十七块弹片","node":"jinsha","date":"1935.04","reviewed":true,"text":"1935 年 4 月初，红军干部休养连到达贵州盘县附近的五里排时遭敌机轰炸。已经隐蔽的贺子珍发现腿部负伤的团政委钟赤兵还躺在担架上，她冲过去替他包扎、往隐蔽处拖，敌机再次俯冲时，又扑在了钟赤兵身上。钟赤兵没有再受伤，贺子珍的头部、上身、四肢却共有 17 块弹片。她醒来后第一件事是询问钟赤兵的情况。","source":"《贺子珍在长征如何救红军伤员？》·新华网","url":"https://www.news.cn/politics/2016-10/16/c_1119727474.htm"},{"id":"story_zhou_enlai","title":"抬出草地","node":"caodi","date":"1935.08","reviewed":true,"text":"到达川西毛儿盖后，周恩来因疲劳过度、营养不足病倒，连续高烧 40 摄氏度不退，确诊为肝脓疡。彭德怀组织担架队抬他过草地，下了死命令：把带不走的迫击炮埋掉，宁可损失一百门大炮，也要把周恩来抬出去。干部团团长陈赓自告奋勇当担架队队长，兵站部部长兼政委杨立三也主动加入担架队。","source":"《解码长征：是谁把重病的周恩来抬出草地》·人民网","url":"http://m.people.cn/n4/2016/0907/c24-7533281.html"},{"id":"story_banjie_pidai","title":"半截皮带","node":"caodi","date":"1936","reviewed":true,"text":"红四方面军 274 团 8 连第 3 次过草地时陷入断粮困境，14 岁的小战士周广才拿出缴获的牛皮腰带，与战友分食一半后，攥紧剩下的半截说：同志们，我们把它留作纪念吧，带着它去延安见毛主席。","source":"《“半截皮带”的时代叩问》·中国军网","url":"http://www.81.mil.cn/zt/2025nzt/hyylctshzzzxjbjzxgx/jbjzxgx/16480352.html","note":"这是红四方面军的故事，不是中央红军。"},{"id":"story_he_jiesheng","title":"18 天的小长征","node":"jiangtaibao","date":"1935.11.19","reviewed":true,"text":"1935 年 11 月 19 日，红二、红六军团主力从湖南桑植县刘家坪和轿子垭地区出发长征。队伍中年龄最小的，是总指挥贺龙刚刚出生 18 天的女儿贺捷生。她回忆：他们把我放在一个小黑骡子上面，我的长征是被父母和无数的叔叔阿姨抱着和背着走的。","source":"《百年瞬间：中国工农红军红二、六军团开始长征》·共产党员网","url":"https://www.12371.cn/2021/11/19/VIDE1637314320431426.shtml","note":"这是红二、红六军团的故事，不是中央红军。"},{"id":"story_17_yongshi","title":"十七勇士","node":"luding","date":"1935.05.25","reviewed":true,"text":"1935 年 5 月 25 日清晨，红一团一营营长孙继先亲自挑选并带领 17 位勇士，分两批乘坐木船，在当地船工的舍命帮助下，向大渡河对岸发起进攻，成功控制对岸渡口。随后，红一军团红一师和干部团 7800 余人迅速过江。","source":"《凭借这艘翘首木船，红军战士渡过不可逾越的天险》·共产党员网","url":"https://www.12371.cn/2021/11/10/ARTI1636516276417977.shtml","note":"原文另有“包括孙继先在内的 18 勇士”的说法。"},{"id":"story_22_yongshi","title":"二十二勇士","node":"luding","date":"1935.05.29","reviewed":true,"text":"红四团冒着大雨在崎岖的山路上跑步前进，一昼夜奔袭 120 公里，于 5 月 29 日凌晨赶到泸定桥西岸。当时桥上三分之二的桥板几乎都被拆掉了，第 2 连连长和 22 名突击队员冒着枪林弹雨，沿着火墙密布的铁索，踩着铁链夺下桥头，并与左岸部队合围占领了泸定桥。","source":"《历史记忆中的长征》第七集“飞夺泸定桥”·共产党员网","url":"https://xuexi.12371.cn/2016/12/16/ARTI1481870706956501.shtml"},{"id":"story_yihai","title":"彝海结盟","node":"luding","date":"1935.05.22","reviewed":true,"text":"1935 年 5 月 22 日，中央红军先遣队司令员刘伯承与彝族果基家支首领小叶丹在四川冕宁彝海畔歃血为盟。结盟当晚，刘伯承把一面红旗赠给小叶丹。此后，红军后续部队沿着这条友谊之路，顺利地通过彝区，迅速抢渡大渡河。","source":"《小叶丹：与红军歃血为盟的彝族英雄》·共产党员网","url":"https://www.12371.cn/2019/01/28/ARTI1548632609522556.shtml"},{"id":"story_deng_redstar","title":"邓小平与长征途中的《红星》报","node":"start","date":"1934.10.20","reviewed":true,"text":"中央红军长征途中，邓小平坚持办《红星》报。1934 年 10 月 20 日，《红星》报油印版第 1 期出版，他为该期撰写社论，鼓舞指战员突破封锁、继续前进。","source":"《长征中的邓小平：跟着走！》·共产党员网","url":"https://www.12371.cn/2024/11/19/ARTI1731979792927993.shtml","note":"关联出发站讲述长征初期的宣传工作，并不表示报纸在中央苏区出发地出版。"},{"id":"story_zhang_wentian_zunyi","title":"张闻天在遵义会议上发言","node":"zunyi","date":"1935.01","reviewed":true,"text":"遵义会议上，张闻天根据会前与毛泽东、王稼祥共同商量的意见，作了反对“左”倾军事错误的报告。","source":"《张闻天：忠于党、忠于人民的一生》·共产党员网","url":"https://www.12371.cn/2019/08/26/ARTI1566780338404706.shtml"},{"id":"story_zhu_de_zunyi","title":"朱德支持纠正军事错误","node":"zunyi","date":"1935.01","reviewed":true,"text":"在遵义会议上，朱德在王稼祥、张闻天之后发言，支持毛泽东关于纠正军事错误的主张。会议后，朱德、周恩来仍为军事指挥者，毛泽东协助周恩来指挥军事。","source":"《朱德在长征中的重大历史贡献》·中共中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2019/0228/c423964-30916641.html"},{"id":"story_mao_lamp","title":"苟坝会议上的马灯","node":"chishui","date":"1935.03","reviewed":true,"text":"1935 年 3 月，苟坝会议讨论是否攻打打鼓新场时，毛泽东认为打鼓新场易守难攻，周边敌军可能赶来，一旦不能迅速攻克，红军会陷入重围，因此反对进攻。当晚他提着马灯去找周恩来商议，周恩来同意暂缓下达命令。随后朱德也参与商议，会议再次讨论后决定放弃进攻。","source":"《1935年春夜苟坝那盏马灯》·中共中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2019/0625/c219021-31193895.html","note":"苟坝会议发生在贵州遵义地区，这里按四渡赤水期间的时间线关联赤水河站。"},{"id":"story_zhang_side_grass","title":"张思德与草地上的野菜","node":"caodi","date":"1935—1936","reviewed":true,"text":"张思德随红四方面军长征，曾三度经过雪山、草地。长征途中，战友在草地发现野菜，他以身试毒，中毒昏迷，经抢救苏醒后提醒大家不要吃。","source":"《为了人民 服务人民——张思德精神述评》·共产党员网","url":"https://www.12371.cn/2021/11/09/ARTI1636462830125270.shtml","note":"这是红四方面军的长征事迹，不应归为中央红军在本图所示草地站的事件。"},{"id":"story_helong_renbishi","title":"贺龙、任弼时与红二方面军","node":"jiangtaibao","date":"1936.07—10","reviewed":true,"text":"1936 年 7 月 5 日，红二方面军在四川甘孜地区成立，贺龙任总指挥，任弼时任政治委员；随后红四、红二方面军共同北上。10 月 22 日，红一、红二方面军在将台堡会师。","source":"《中国共产党一百年大事记》·中共中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2021/0628/c423712-32142427.html","note":"红二方面军成立地点在甘孜地区；将台堡是后来会师地点。"}];
const json = (value, status = 200) => Response.json(value, {status, headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});
const MAX_BODY = 12000;
const SESSION_RE=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
const encode64 = bytes => btoa(Array.from(bytes, b=>String.fromCharCode(b)).join('')).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
function decode64(value){if(!/^[A-Za-z0-9_-]+$/.test(value))throw new Error('invalid token');const binary=atob(value.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-value.length%4)%4));return Uint8Array.from(binary,c=>c.charCodeAt(0));}
async function signingKey(secret){return crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);}
async function issueToken(key,entry){const payload=encode64(new TextEncoder().encode(JSON.stringify(entry)));const signature=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(payload));return payload+'.'+encode64(new Uint8Array(signature));}
async function readToken(key,token,sessionId,node){try{if(typeof token!=='string'||token.length>7000)return null;const parts=token.split('.');if(parts.length!==2)return null;const valid=await crypto.subtle.verify('HMAC',key,decode64(parts[1]),new TextEncoder().encode(parts[0]));if(!valid)return null;const entry=JSON.parse(new TextDecoder().decode(decode64(parts[0])));if(entry.v!==1||entry.sessionId!==sessionId||entry.node!==node||!Number.isSafeInteger(entry.at)||entry.at>Date.now()+60000||Date.now()-entry.at>3600000||typeof entry.question!=='string'||entry.question.length>500||typeof entry.answer!=='string'||entry.answer.length>800||!Array.isArray(entry.sources)||entry.sources.some(id=>typeof id!=='string'||!evidence.some(e=>e.id===id)))return null;return entry;}catch{return null;}}

const TYPES=new Set(['history','chat','off_topic']);
const ROUTE_KEYS=new Set(['overview','turning','journey','full']);
const NO_DATA='现有资料不足以可靠回答这个问题，请换个问法或查阅节点资料。';
const evidence=[...nodes.flatMap(n=>[{id:n.id,name:n.name,text:n.text,source:n.source,url:n.url},...(n.extra||[]).map(e=>({...e,name:n.name}))]),
  // 已审核的长征故事也作为资料，标明“故事”和所属节点
  ...stories.filter(st=>st.reviewed===true).map(st=>({id:st.id,name:'故事·'+st.title+'（'+(nodes.find(n=>n.id===st.node)?.name||st.node)+'）',text:st.text,source:st.source,url:st.url}))];
const nodeName=id=>nodes.find(n=>n.id===id)?.name||id;

// 限流：每个运行实例在内存中计数，属尽力而为；可靠的费用上限仍需在模型服务账户侧设置。
const buckets=new Map();let hourly={start:0,count:0};
function clientIp(request){return (request.headers.get('cf-connecting-ip')||request.headers.get('x-real-ip')||(request.headers.get('x-forwarded-for')||'').split(',')[0]||'').trim();}
function rateLimit(request,env,kind){
  const now=Date.now(),windowMs=10*60*1000;
  const perIp=Number(env[kind==='plan'?'PLAN_LIMIT_PER_IP':'CHAT_LIMIT_PER_IP'])||(kind==='plan'?10:30);
  const perHour=Number(env.MODEL_LIMIT_PER_HOUR)||600;
  if(now-hourly.start>3600000)hourly={start:now,count:0};
  if(hourly.count>=perHour)return '讲解员当前访问量较大，请稍后再试。';
  const ip=clientIp(request);
  if(ip){
    const k=kind+':'+ip;let b=buckets.get(k);
    if(!b||now-b.start>windowMs){b={start:now,count:0};buckets.set(k,b);}
    if(b.count>=perIp)return '提问太频繁了，请过几分钟再试。';
    b.count++;
    if(buckets.size>5000)for(const [key,v] of buckets)if(now-v.start>windowMs)buckets.delete(key);
  }
  hourly.count++;return '';
}
const tooMany=message=>Response.json({error:message},{status:429,headers:{'cache-control':'no-store','x-content-type-options':'nosniff','retry-after':'600'}});

async function callModel(env,messages,maxTokens,signal){
  return fetch('https://api.deepseek.com/chat/completions',{method:'POST',headers:{'content-type':'application/json','authorization':'Bearer '+env.DEEPSEEK_API_KEY},signal,body:JSON.stringify({model:env.DEEPSEEK_MODEL||'deepseek-chat',messages,response_format:{type:'json_object'},temperature:0.2,max_tokens:maxTokens})});
}
// 去掉网址、Markdown 链接，以及谈论“链接/网址”的句子（来源链接由页面根据 sources 展示）。
function stripLinks(text){
  return text.replace(/\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/https?:\/\/[^\s）)]+/gi,'').split(/(?<=[。！？!?\n])/).filter(part=>!/(链接|网址|网页地址|URL)/i.test(part)).join('').trim();
}
// 汉字数字转数值，例如“十七”→17、“二十五”→25、“一万”→10000。
const CN_DIGITS={零:0,〇:0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9,十:10,百:100,千:1000,万:10000};
function cnToNumber(text){let total=0,section=0,digit=0;for(const ch of text){const v=CN_DIGITS[ch];if(v==null)return null;if(v===10000){total+=(section+digit)*v;section=0;digit=0;}else if(v>=10){section+=(digit||1)*v;digit=0;}else digit=v;}return total+section+digit;}
const arabicIn=text=>(String(text).match(/\d+/g)||[]).map(x=>String(Number(x)));
// 资料一侧：所有阿拉伯数字和汉字数字都算作“出现过”，宁可宽一些，避免误杀。
const numbersAllowedIn=text=>[...arabicIn(text),...[...String(text).matchAll(/[零〇一二两三四五六七八九十百千万]+/g)].map(m=>cnToNumber(m[0])).filter(v=>v!=null).map(String)];
// 回答一侧：阿拉伯数字，以及与量词连用的汉字数量（“三个月”“十七名”“两个团”），不含“第一次”这类序数和部队番号。
// 不含“军、师、团、营、连”等：它们多出现在部队番号（红二十五军、红四团）或“两军”“三军会师”这类泛称中，不是数量。
const CN_QUANTITY=/(?<!第)([零〇一二两三四五六七八九十百千万]+)(?=[个名人条次天年月日夜里座根艘只路批位])/g;
// “两个故事”“三个方面”这类是在组织回答，不是史实中的数量，不核对。
const META_AFTER=/^个(故事|问题|方面|节点|站|原因|例子|资料|地方|阶段|角度|要点)/;
const numbersClaimedIn=text=>[...arabicIn(text),...[...String(text).matchAll(CN_QUANTITY)].filter(m=>!META_AFTER.test(String(text).slice(m.index+m[1].length))).map(m=>cnToNumber(m[1])).filter(v=>v!=null).map(String)];
// 回答里的数字必须出现在所引资料或用户问题中。
function unsupportedNumbers(answer,ids,question){
  const allowed=new Set([...ids.flatMap(id=>numbersAllowedIn(evidence.find(e=>e.id===id).text)),...numbersAllowedIn(question)]);
  return [...new Set(numbersClaimedIn(answer).filter(n=>!allowed.has(n)))];
}
// 回答中的书名号内容（文件、文章名）必须与所引资料或用户问题中的写法完全一致。
const squash=text=>String(text).replace(/\s+/g,'');
function unsupportedTitles(answer,ids,question){
  const pool=squash(ids.map(id=>evidence.find(e=>e.id===id).text).join('')+question);
  return [...new Set([...String(answer).matchAll(/《([^》]{2,60})》/g)].map(m=>m[1]).filter(t=>!pool.includes(squash(t))))];
}
// 针对验收中已观察到的几类高风险表述做保守拦截；这不是通用事实核验。
function observedRisks(answer,ids,question){
  const compact=squash(answer), q=squash(question), issues=[];
  const cited=ids.map(id=>evidence.find(e=>e.id===id)?.text||'').join('');
  if ((/草地/.test(compact)||/草地/.test(q)) && /(?:损失|伤亡|牺牲|死亡).{0,24}(?:主要|因为|由于|导致)/.test(compact) && !/(?:资料|记载).{0,12}(?:未说明|没有说明|不足)/.test(compact)) issues.push('资料未说明草地损失的主要原因，不要据环境和补给困难自行归因');
  if (/1934年11月下旬至12月初/.test(compact) && /三道封锁线/.test(compact)) issues.push('三道封锁线对应的时间是1934年10月下旬至12月初，不能更改时段');
  if (/伤亡|死亡|牺牲/.test(q) && /湘江/.test(compact) && /(?:8\.6|8．6)/.test(compact) && /3万/.test(compact)) issues.push('伤亡问题中不要使用从出发到突破封锁后的兵力变化代替湘江单场战役伤亡；可说明资料没有给出战役伤亡人数');
  if (/塔山湾/.test(compact) && !/塔山湾/.test(cited)) issues.push('关于塔山湾的表述没有引用相应资料');
  if (/事实上确立.{0,24}领导地位/.test(compact) && !/事实上确立.{0,24}领导地位/.test(squash(cited))) issues.push('关于事实上确立领导地位的表述缺少支持该事实的资料');
  return issues;
}
// 闲聊或无关回答不附出处，因此不得陈述史实：删除其中带史实迹象的陈述句，保留“你可以问我……”这类引导句。
const HISTORY_HINT=/红[一二三四六]|红军|方面军|军团|会议|战役|战斗|会师|渡江|渡河|毛泽东|周恩来|朱德|张闻天|刘伯承|\d{4}\s*年/;
const SUGGESTION=/可以问|想了解|不妨|比如|例如|你可以|带你|选择|路线|节点|问我|陪你/;
function dropUnsourcedFacts(text){
  return text.split(/(?<=[。！？!?；;\n])/).filter(part=>!(HISTORY_HINT.test(part.replace(/长征/g,''))&&!SUGGESTION.test(part))).join('').trim();
}
function cleanAction(action,current){
  if(!action||typeof action!=='object')return null;
  if(action.type==='goto'&&typeof action.node==='string'&&nodes.some(n=>n.id===action.node)&&action.node!==current)return {type:'goto',node:action.node};
  if(action.type==='next'||action.type==='skip')return {type:action.type};
  if(action.type==='route'&&ROUTE_KEYS.has(action.route))return {type:'route',route:action.route};
  return null;
}
function cleanFollowups(list,question){
  if(!Array.isArray(list))return [];
  return [...new Set(list.filter(q=>typeof q==='string').map(q=>q.trim()).filter(q=>q&&q.length<=30&&!/https?:|www\.|链接|网址/i.test(q)&&q!==question))].slice(0,2);
}
function cleanTour(tour){
  if(!tour||typeof tour!=='object')return null;
  const ids=list=>Array.isArray(list)?[...new Set(list.filter(id=>typeof id==='string'&&nodes.some(n=>n.id===id)))].slice(0,nodes.length):[];
  const route=ids(tour.route);
  return route.length?{route,visited:ids(tour.visited)}:null;
}
function checkReply(parsed,question,current){
  let type=TYPES.has(parsed.type)?parsed.type:'history';
  let ids=Array.isArray(parsed.sources)?[...new Set(parsed.sources.filter(id=>typeof id==='string'&&evidence.some(e=>e.id===id)))].slice(0,4):[];
  let answer=stripLinks(parsed.answer).slice(0,1200);
  // 自称闲聊却引用资料或带年份时，按历史问题处理，避免绕过来源要求。
  if(type!=='history'&&(ids.length||/\d{3,}/.test(answer)))type='history';
  let badNumbers=[],badTitles=[],risks=[];
  if(type==='history'){
    if(!ids.length||!answer){answer=NO_DATA;ids=[];}
    else{badNumbers=unsupportedNumbers(answer,ids,question);badTitles=unsupportedTitles(answer,ids,question);risks=observedRisks(answer,ids,question);}
  }else{
    ids=[];answer=(dropUnsourcedFacts(answer)||'我是长征讲解员小征，可以问我长征相关的问题。').slice(0,300);
  }
  return {type,ids,answer,badNumbers,badTitles,risks,action:cleanAction(parsed.action,current),followups:cleanFollowups(parsed.followups,question)};
}

// 沙盘鸟瞰图（构建时由 scripts/generate.mjs 以 base64 填入）
